"use strict";(globalThis.webpackChunkgsf_docusaurus_template=globalThis.webpackChunkgsf_docusaurus_template||[]).push([[4006],{5346(e){e.exports=JSON.parse('{"tag":{"label":"persona:data-engineer","permalink":"/tags/persona-data-engineer","allTagsPath":"/tags","count":5,"items":[{"id":"development/data-handling/compress-stored-data","title":"Compress stored data","description":"Storing uncompressed data wastes bandwidth and increases storage capacity requirements; applying appropriate compression reduces both storage consumption and the energy needed to read and write it.","permalink":"/development/data-handling/compress-stored-data"},{"id":"operations/resource-lifecycle/delete-or-auto-expire-unused-storage","title":"Delete or auto-expire unused storage","description":"Storage that is no longer used still occupies hardware and carries embodied carbon. Deleting unused storage, either manually or through automated retention policies, reduces the hardware needed to hold data, provided deletion is controlled so that data still needed is not lost.","permalink":"/operations/resource-lifecycle/delete-or-auto-expire-unused-storage"},{"id":"development/pre-trained-transfer-learning","title":"Leverage pre-trained models and transfer learning","description":"Fine-tune existing pre-trained models instead of training from scratch to dramatically reduce the compute, energy, and time required for model development.","permalink":"/development/pre-trained-transfer-learning"},{"id":"operations/resource-lifecycle/optimise-storage-resource-utilisation","title":"Optimise storage utilization","description":"It\'s better to maximise storage utilisation so the storage layer is optimised for the task, not only in terms of energy proportionality but also in terms of embodied carbon. Two storage units running at low utilization rates will consume more energy than one running at a high utilization rate. In addition, the unused capacity on the underutilised storage unit could be more efficiently used for another task or process.","permalink":"/operations/resource-lifecycle/optimise-storage-resource-utilisation"},{"id":"development/data-handling/optimize-data-storage-ai-training","title":"Optimize data storage formats for AI training and inference","description":"Use efficient storage formats, compression, and indexing strategies for AI datasets and embeddings to reduce storage footprint, data transfer, and retrieval compute.","permalink":"/development/data-handling/optimize-data-storage-ai-training"}],"unlisted":false}}')}}]);